Q: Getting the compiler to tell which part of concept conjunction failed A: <p>Here is one solution. The idea is keep an alias of the type that failed, and try to use a function that is deleted for everything except a sentinel (in this case void):</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;type_traits&gt;
#include &lt;vector&gt;
#include &lt;variant&gt;

template&lt;template&lt;class&gt; class UpdateResultType, class Sink, class T&gt;
using update_func_t = UpdateResultType&lt;T&gt; (*)(Sink&amp;, T);

template&lt;class UpdateTraits, template&lt;class&gt; class R, class Sink, class... Types&gt;
struct has_applicable_update
{
    using result = void;
};

template&lt;class UpdateTraits, template&lt;class&gt; class R, class Sink, class T, class... Types&gt;
struct has_applicable_update&lt;UpdateTraits, R, Sink, T, Types...&gt;
{
    static constexpr auto current_value = requires(update_func_t&lt;R, Sink, T&gt;&amp; cb) {
        { cb = &amp;UpdateTraits::update };
    };

    using result = std::conditional_t&lt;
        current_value,
        typename has_applicable_update&lt;UpdateTraits, R, Sink, Types...&gt;::result,
        T
    &gt;;
};

template&lt;class T&gt;
consteval bool concept_satisfied_for_type() = delete;

template&lt;&gt;
consteval bool concept_satisfied_for_type&lt;void&gt;()
{ return true; }

template&lt;class UpdateTraits, template&lt;class&gt; class UpdateResultType, class Sink, class... Types&gt;
concept update_traits = concept_satisfied_for_type&lt;typename has_applicable_update&lt;UpdateTraits, UpdateResultType, Sink, Types...&gt;::result&gt;();

template&lt;update_traits&lt;std::add_pointer_t, std::vector&lt;std::variant&lt;int, double&gt;&gt;&amp;, int, double&gt; UpdateTraits&gt;
void do_stuff();

struct my_traits{
    static int* update(std::vector&lt;std::variant&lt;int, double&gt;&gt;&amp;, int);
    //static double* update(std::vector&lt;std::variant&lt;int, double&gt;&gt;&amp;, double);
};

int main()
{
    do_stuff&lt;my_traits&gt;();
}
</code></pre>
<p>If the concept is satisfied, <code>typename has_applicable_update&lt;UpdateTraits, UpdateResultType, Sink, Types...&gt;::result</code> is <code>void</code>, and concept_satisfied_for_type returns true. Otherwise, it tried to call the deleted specialization, and substitution fails:</p>
<pre><code>&lt;source&gt;: In function 'int main()':
&lt;source&gt;:53:24: error: no matching function for call to 'do_stuff&lt;my_traits&gt;()'
   53 |     do_stuff&lt;my_traits&gt;();
      |     ~~~~~~~~~~~~~~~~~~~^~
&lt;source&gt;:53:24: note: there is 1 candidate
&lt;source&gt;:39:6: note: candidate 1: 'template&lt;class UpdateTraits&gt;  requires  update_traits&lt;UpdateTraits, std::add_pointer_t, std::vector&lt;std::variant&lt;int, double&gt;, std::allocator&lt;std::variant&lt;int, double&gt; &gt; &gt;&amp;, int, double&gt; void do_stuff()'
   39 | void do_stuff();
      |      ^~~~~~~~
&lt;source&gt;:39:6: note: template argument deduction/substitution failed:
&lt;source&gt;:39:6: note: constraints not satisfied
&lt;source&gt;: In substitution of 'template&lt;class UpdateTraits&gt;  requires  update_traits&lt;UpdateTraits, std::add_pointer_t, std::vector&lt;std::variant&lt;int, double&gt;, std::allocator&lt;std::variant&lt;int, double&gt; &gt; &gt;&amp;, int, double&gt; void do_stuff() [with UpdateTraits = my_traits]':
&lt;source&gt;:53:24:   required from here
   53 |     do_stuff&lt;my_traits&gt;();
      |     ~~~~~~~~~~~~~~~~~~~^~
&lt;source&gt;:36:9:   required for the satisfaction of 'update_traits&lt;UpdateTraits, std::add_pointer_t, std::vector&lt;std::variant&lt;int, double&gt;, std::allocator&lt;std::variant&lt;int, double&gt; &gt; &gt;&amp;, int, double&gt;' [with UpdateTraits = my_traits]
&lt;source&gt;:36:139: error: use of deleted function 'consteval bool concept_satisfied_for_type() [with T = double]'
   36 | concept update_traits = concept_satisfied_for_type&lt;typename has_applicable_update&lt;UpdateTraits, UpdateResultType, Sink, Types...&gt;::result&gt;();
</code></pre>
<p>GCC 16 emits a god error message when using std::is_same_v. This one works also for GCC 15.</p>

Q: How to mimic designated initializers? A: <p>You can use the builder pattern to get something that looks like this:</p>
<pre class="lang-cpp prettyprint-override"><code>constexpr auto ServicesNames = ArrayBuilder&lt;std::string_view&gt;()
    .e&lt;bitbucket&gt;(&quot;https://bitbucket.org/.*&quot;)
    .e&lt;github&gt;(&quot;https://github.com/.*&quot;)
    .e&lt;gitlab&gt;(&quot;https://gitlab.com/.*&quot;)
    .build();
</code></pre>
<p>Implementation (<a href="https://godbolt.org/z/ePa739Ta4" rel="nofollow noreferrer">https://godbolt.org/z/ePa739Ta4</a>):</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;tuple&gt;
#include &lt;algorithm&gt;
#include &lt;cstddef&gt;
#include &lt;array&gt;

template&lt;std::size_t I, typename... Args&gt;
struct Part {
    std::tuple&lt;Args...&gt; args;
    static constexpr std::size_t index = I;
};

template&lt;typename T, typename... Parts&gt;
struct ArrayBuilder {
    std::tuple&lt;Parts...&gt; parts;

    template&lt;auto I, typename... Args&gt;
    constexpr auto e(Args&amp;&amp;... args) &amp;&amp; {
        static constexpr std::size_t index = static_cast&lt;std::size_t&gt;(I);
        static_assert(((index != Parts::index) &amp;&amp; ...), &quot;index appears multiple times!&quot;);
        return std::apply([&amp;](auto&amp;... parts) {
            using new_part_type = Part&lt;index, Args&amp;&amp;...&gt;;
            return ArrayBuilder&lt;T, Parts..., new_part_type&gt;{
                std::tuple&lt;Parts..., new_part_type&gt;(
                    std::move(parts)...,
                    new_part_type{ std::tuple&lt;Args&amp;&amp;...&gt;(std::forward&lt;Args&gt;(args)...) }
                )
            };
        }, parts);
    }

private:
    static constexpr std::size_t max_index = std::max({ 0zu, Parts::index... });

    template&lt;std::size_t I, std::size_t J = 0&gt;
    constexpr T initialize_for_index() {
        if constexpr (J == sizeof...(Parts)) {
            return T();
        } else if constexpr (std::tuple_element_t&lt;J, std::tuple&lt;Parts...&gt;&gt;::index == I) {
            return std::apply([]&lt;typename... Args&gt;(Args&amp;&amp;... args) {
                return T(std::forward&lt;Args&gt;(args)...);
            }, std::get&lt;J&gt;(parts).args);
        } else {
            return initialize_for_index&lt;I, J+1zu&gt;();
        }
    }

public:
    constexpr auto build() &amp;&amp; {
        return [&amp;]&lt;std::size_t... I&gt;(std::index_sequence&lt;I...&gt;) {
            return std::array&lt;T, max_index+1zu&gt;{ {
                initialize_for_index&lt;I&gt;()...
            } };
        }(std::make_index_sequence&lt;max_index+1zu&gt;{});
    }
};
</code></pre>

Q: How can I validate menu input (1–4) and prevent my C program from terminating on invalid character input? A: <p>In order to read a line from the user, you can use the function <a href="https://cppreference.com/c/io/fgets" rel="nofollow noreferrer"><code>fgets</code></a> from the C standard library.</p>
<p>In order to convert the content of this line from a string of characters to an <code>int</code>, you can use the function <a href="https://cppreference.com/c/string/byte/strtol" rel="nofollow noreferrer"><code>strtol</code></a> from the C standard library.</p>
<p>These two functions can be combined into a single function, which automatically reprompts the user for input if something is wrong with it. The function <code>get_int_from_user</code> from <a href="https://stackoverflow.com/a/73915292/12149471">this answer of mine to another question</a> does exactly this. See my answer to the other question for more information on how that function works.</p>
<p>If you want to also ensure that the converted <code>int</code> is in the range <code>1</code> to <code>4</code>, and reprompt the user if this is not the case, then you can call my function <code>get_int_from_user</code> in a loop, like this:</p>
<pre class="lang-c prettyprint-override"><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;ctype.h&gt;
#include &lt;limits.h&gt;
#include &lt;errno.h&gt;

int get_int_from_user( const char *prompt );

int main( void )
{
    int input;

    // repeat until input is valid
    for (;;)
    {
        input = get_int_from_user( &quot;Please enter a number between 1 and 4: &quot; );

        if ( input &lt; 1 || input &gt; 4 )
        {
            printf( &quot;Error: Input must be between 1 and 4!\n&quot; );
            continue;
        }

        // input was ok, so we can break out of the loop
        break;
    }

    printf( &quot;Input is valid.\n&quot; );
    printf( &quot;You entered: %d\n&quot;, input );
}

// This function will attempt to read one integer of type &quot;int&quot;
// from the user. If the input is invalid, it will automatically
// reprompt the user, until the input is valid.
int get_int_from_user( const char *prompt )
{
    // loop forever until user enters a valid number
    for (;;)
    {
        char buffer[1024], *p;
        long num;

        // prompt user for input
        fputs( prompt, stdout );

        // explicitly flushing the output stream
        // may be necessary on some platforms
        fflush( stdout );

        // get one line of input from input stream
        if ( fgets( buffer, sizeof buffer, stdin ) == NULL )
        {
            fprintf( stderr, &quot;Unrecoverable input error!\n&quot; );
            exit( EXIT_FAILURE );
        }

        // make sure that entire line was read in (i.e. that
        // the buffer was not too small)
        if ( strchr( buffer, '\n' ) == NULL &amp;&amp; !feof( stdin ) )
        {
            int c;

            printf( &quot;Input line was too long!\n&quot; );

            // discard remainder of line
            do
            {
                c = getchar();

                if ( c == EOF )
                {
                    fprintf( stderr, &quot;Unrecoverable error reading from input!\n&quot; );
                    exit( EXIT_FAILURE );
                }

            } while ( c != '\n' );

            continue;
        }

        // attempt to convert string to number
        errno = 0;
        num = strtol( buffer, &amp;p, 10 );
        if ( p == buffer )
        {
            printf( &quot;Error converting string to number!\n&quot; );
            continue;
        }

        // make sure that number is representable as an &quot;int&quot;
        if ( errno == ERANGE || num &lt; INT_MIN || num &gt; INT_MAX )
        {
            printf( &quot;Number out of range error!\n&quot; );
            continue;
        }

        // make sure that remainder of line contains only whitespace,
        // so that input such as &quot;6abc&quot; gets rejected
        for ( ; *p != '\0'; p++ )
        {
            if ( !isspace( (unsigned char)*p ) )
            {
                printf( &quot;Unexpected input encountered!\n&quot; );

                // cannot use `continue` here, because that would go to
                // the next iteration of the innermost loop, but we
                // want to go to the next iteration of the outer loop
                goto continue_outer_loop;
            }
        }

        return num;

    continue_outer_loop:
        continue;
    }
}
</code></pre>
<p>This program has the following behavior:</p>
<pre class="lang-none prettyprint-override"><code>Please enter a number between 1 and 4: abc
Error converting string to number!
Please enter a number between 1 and 4: 6abc
Unexpected input encountered!
Please enter a number between 1 and 4: 6#
Unexpected input encountered!
Please enter a number between 1 and 4: 6
Error: Input must be between 1 and 4!
Please enter a number between 1 and 4: 3
Input is valid.
You entered: 3
</code></pre>
